<div class="page-title"><div><em>CARD CENTER</em><h1><?=tl('cards_title')?></h1><p><?=tl('cards_sub')?></p></div><button class="btn" data-modal="card-modal">+ <?=tl('add_card')?></button></div><?php if(!$cards):?><div class="empty">No cards are linked to your accounts yet. Use "Add a card" to issue one.</div><?php endif?><?php foreach($cards as $c):?><div class="grid card-grid"><article class="bank-card"><div><a class="brand brand-light"><i><b></b><b></b><b></b></i>North<span>West</span></a><strong><?=html_escape($c['network'])?></strong></div><i class="chip"></i><h3><?=html_escape($c['masked_number'])?></h3><footer><span><small>CARDHOLDER</small><?=html_escape($c['cardholder_name'])?></span><span><small>EXPIRES</small><?=sprintf('%02d/%02d',$c['expiry_month'],$c['expiry_year']%100)?></span></footer></article><section class="panel controls"><h2>Card controls</h2><?php if($c['status']==='active'):?><form method="post" action="<?=site_url('cards/'.$c['id'].'/report-lost')?>" class="lost-card" onsubmit="return confirm('Report this card as lost or stolen? It will be blocked immediately.');"><div><b>Report lost / stolen</b><small>Block this card immediately and order a replacement</small></div><button class="btn danger-btn">Report lost</button></form><?php endif?><?php $controls=array('is_frozen'=>array('▣','Freeze card','Temporarily block all transactions'),'international_enabled'=>array('◎','International payments','Allow purchases outside the US'),'online_enabled'=>array('▤','Online payments','Allow online and in-app purchases'));foreach($controls as $field=>$info):?><form method="post" action="<?=site_url('cards/'.$c['id'].'/toggle')?>"><input type="hidden" name="<?=$this->security->get_csrf_token_name()?>" value="<?=$this->security->get_csrf_hash()?>"><input type="hidden" name="field" value="<?=$field?>"><i><?=$info[0]?></i><div><b><?=$info[1]?></b><small><?=$info[2]?></small></div><button class="switch <?=$c[$field]?'on':''?>"><i></i></button></form><?php endforeach?></section></div><?php endforeach?>

<dialog id="card-modal"><div class="dialog-head"><h2>Add a card</h2><button data-close>×</button></div><?=form_open('cards/create')?><label>Linked account</label><select name="account_id" required><?php foreach($accounts as $a):?><option value="<?=$a['id']?>"><?=html_escape($a['name'])?> •<?=substr($a['account_number'],-4)?></option><?php endforeach?></select><label>Cardholder name</label><input name="cardholder_name" value="<?=html_escape(($current_user['first_name']??'').' '.($current_user['last_name']??''))?>"><div class="form-grid"><div><label>Type</label><select name="card_type"><option value="virtual">Virtual</option><option value="physical">Physical</option></select></div><div><label>Daily limit</label><input name="daily_limit" type="number" value="10000" min="1" step="1"></div></div><button class="btn wide">Issue card</button></form></dialog>
